<div class="page-heading"><div><span class="eyebrow">Hospital dashboard</span><h1><?= e($hospital['name']) ?></h1><p>Approved appointments arrive here after administrator review.</p></div><a class="button" href="<?= e(url('hospital.inventory')) ?>">Update vaccine status</a></div>
